import{_ as t,o as i,c as s,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"Loi sur la Garantie de l'Éducation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/43-教育保障法.md","filePath":"fr/43-教育保障法.md","lastUpdated":null}`),a={name:"fr/43-教育保障法.md"};function o(r,e,l,u,d,c){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="loi-sur-la-garantie-de-l-education" tabindex="-1">Loi sur la Garantie de l&#39;Éducation <a class="header-anchor" href="#loi-sur-la-garantie-de-l-education" aria-label="Permalink to &quot;Loi sur la Garantie de l&#39;Éducation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>43</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Droit à l&#39;éducation, Éducation symbiotique, Transmission de la culture, Apprentissage tout au long de la vie, Équité éducative</td></tr></tbody></table><h2 id="i-objectif-legislatif-et-principes-fondamentaux" tabindex="-1">I. Objectif Législatif et Principes Fondamentaux <a class="header-anchor" href="#i-objectif-legislatif-et-principes-fondamentaux" aria-label="Permalink to &quot;I. Objectif Législatif et Principes Fondamentaux&quot;">​</a></h2><p>La <em>Loi sur la Garantie de l&#39;Éducation</em> est l&#39;une des cinq lois d&#39;accompagnement de la Civilisation Symbiotique de l&#39;Ancre. Elle vise à garantir le droit à l&#39;éducation de toutes les vies au sein de l&#39;Univers Hengyuan, à établir un système éducatif ayant pour concept fondamental l&#39;« évolution symbiotique », et à fournir le soutien en connaissances et en talents pour la progression commune des Dix Mille Races.</p><p>Cette Loi établit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Équité éducative</td><td>Toutes les vies, sans distinction de race, de culture ou de naissance, jouissent d&#39;opportunités éducatives égales</td></tr><tr><td>Enseignement selon les aptitudes</td><td>Respecte les différences de talents et les choix de voie d&#39;évolution de chaque vie, fournissant des plans éducatifs personnalisés</td></tr><tr><td>Unité de la connaissance et de l&#39;action</td><td>Combine les connaissances théoriques et la culture pratique ; contre l&#39;éducation par discours vide déconnectée de la réalité</td></tr><tr><td>Ouverture et partage</td><td>Les ressources éducatives sont ouvertes à toute la société ; les méthodes de base des Trois Cents Systèmes de Culture Originels sont enseignées gratuitement</td></tr><tr><td>Apprentissage tout au long de la vie</td><td>L&#39;éducation traverse tout le processus de la vie, soutenant l&#39;apprentissage continu et l&#39;amélioration des capacités à toutes les étapes</td></tr><tr><td>Pluralisme culturel</td><td>Respecte les traditions culturelles de toutes les races, encourage les échanges culturels pluralistes et l&#39;apprentissage mutuel</td></tr></tbody></table><h2 id="ii-garanties-juridiques-du-droit-a-l-education" tabindex="-1">II. Garanties Juridiques du Droit à l&#39;Éducation <a class="header-anchor" href="#ii-garanties-juridiques-du-droit-a-l-education" aria-label="Permalink to &quot;II. Garanties Juridiques du Droit à l&#39;Éducation&quot;">​</a></h2><p>Cette Loi stipule explicitement que le droit à l&#39;éducation est un droit fondamental conféré à chaque vie par la Constitution Symbiotique, et que l&#39;État et la civilisation ont l&#39;obligation de garantir la réalisation de ce droit :</p><ol><li><strong>Éducation de base gratuite</strong> : toutes les vies ont le droit de recevoir une éducation de base gratuite, comprenant les connaissances générales, les méthodes de culture de base, les concepts de la civilisation symbiotique, etc. La durée de scolarité est de six à douze ans, ajustée selon le cycle de développement de chaque race.</li><li><strong>Initiation gratuite à la culture</strong> : les méthodes de base des Trois Cents Systèmes de Culture Originels sont ouvertes à toutes les vies gratuitement ; aucune organisation ni aucun individu ne peut s&#39;approprier les méthodes de culture de base comme propriété privée et les enseigner contre rémunération.</li><li><strong>Égalité des chances d&#39;avancement</strong> : les institutions éducatives de tous les niveaux ne doivent pas fixer de conditions discriminatoires fondées sur la race, la culture ou la naissance dans les admissions ; les critères d&#39;admission sont ouverts et transparents.</li><li><strong>Garanties d&#39;éducation spéciale</strong> : fournir des ressources éducatives spéciales adaptées et un soutien d&#39;enseignement à distance pour les groupes tels que les vies handicapées, les vies d&#39;autres races et les vies des plans éloignés.</li><li><strong>Institution d&#39;aide éducative</strong> : fournir des bourses, des bourses d&#39;excellence et des prêts sans intérêt aux apprenants en difficulté financière, garantissant que personne ne perd l&#39;opportunité d&#39;éducation pour des raisons économiques.</li></ol><h2 id="iii-architecture-du-systeme-educatif" tabindex="-1">III. Architecture du Système Éducatif <a class="header-anchor" href="#iii-architecture-du-systeme-educatif" aria-label="Permalink to &quot;III. Architecture du Système Éducatif&quot;">​</a></h2><p>Le système éducatif de la Civilisation Symbiotique de l&#39;Ancre est divisé en quatre niveaux, reliés organiquement entre eux :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Nom</th><th>Objectif</th><th>Durée de scolarité</th></tr></thead><tbody><tr><td>Premier niveau</td><td>Éducation d&#39;initiation</td><td>Développer les capacités cognitives de base et la conscience symbiotique ; enseigner les méthodes de culture de base</td><td>3-6 ans</td></tr><tr><td>Deuxième niveau</td><td>Éducation de base</td><td>Apprentissage systématique des connaissances générales et de la théorie de la culture ; découvrir les directions de talents individuels</td><td>6-9 ans</td></tr><tr><td>Troisième niveau</td><td>Éducation professionnelle</td><td>Apprentissage approfondi et pratique dans le système de culture choisi ou le domaine professionnel</td><td>3-10 ans</td></tr><tr><td>Quatrième niveau</td><td>Recherche avancée</td><td>Exploration de pointe et recherche innovante pour les cultivateurs avancés et les chercheurs</td><td>Illimité</td></tr></tbody></table><p>En outre, une « Institution du réseau de mentors » est établie : les cultivateurs qui atteignent un certain stade de culture ont l&#39;obligation de guider les cultivateurs débutants dans la mesure de leurs capacités ; les contributions d&#39;encadrement sont comptabilisées dans le montant de contribution du Mécanisme de Contrat Conjoint de Production et reçoivent l&#39;allocation de ressources correspondante.</p><h2 id="iv-institutions-educatives-et-enseignants" tabindex="-1">IV. Institutions Éducatives et Enseignants <a class="header-anchor" href="#iv-institutions-educatives-et-enseignants" aria-label="Permalink to &quot;IV. Institutions Éducatives et Enseignants&quot;">​</a></h2><ul><li><strong>Institutions éducatives publiques</strong> : établies par l&#39;État ou la communauté civilisationnelle, assurant l&#39;éducation de base gratuite et les services éducatifs publics, avec un financement garanti par l&#39;accumulation publique.</li><li><strong>Institutions éducatives privées</strong> : établies par des forces sociales conformément à la loi ; elles peuvent percevoir des frais raisonnables, mais doivent accepter la supervision des autorités éducatives compétentes et ne doivent pas faire de publicité mensongère ni de facturation prédatrice.</li><li><strong>Sectes de culture</strong> : les organisations traditionnelles de culture peuvent, après enregistrement, exercer en tant qu&#39;institutions éducatives professionnelles ; elles doivent respecter la loi sur l&#39;éducation et ne doivent pas fermer et monopoliser les ressources de culture.</li><li><strong>Droits et obligations des enseignants</strong> : les enseignants jouissent de droits tels que la liberté académique, une rémunération raisonnable et la formation professionnelle, tout en portant des obligations telles qu&#39;éduquer les élèves, montrer l&#39;exemple et protéger la vie privée des étudiants.</li></ul><h2 id="v-contenu-educatif-et-normes-de-programmes" tabindex="-1">V. Contenu Éducatif et Normes de Programmes <a class="header-anchor" href="#v-contenu-educatif-et-normes-de-programmes" aria-label="Permalink to &quot;V. Contenu Éducatif et Normes de Programmes&quot;">​</a></h2><p>Le contenu éducatif doit satisfaire aux exigences suivantes :</p><ol><li>Inclure les concepts fondamentaux de la civilisation symbiotique et l&#39;éducation contre la prédation, cultivant la conscience symbiotique des apprenants.</li><li>Inclure les théories fondamentales et les méthodes d&#39;initiation des Trois Cents Systèmes de Culture Originels.</li><li>Inclure les connaissances scientifiques générales telles que les lois cosmiques, les connaissances sur les plans et les sciences de la vie.</li><li>Inclure l&#39;histoire et la culture des Dix Mille Races, favorisant la compréhension et le respect mutuels entre les races.</li><li>Inclure des composantes de culture pratique et de service social, cultivant la capacité d&#39;unir la connaissance et l&#39;action.</li><li>Interdire la diffusion de concepts de culture prédatrice et d&#39;idées discriminatoires.</li></ol><h2 id="vi-responsabilite-juridique" tabindex="-1">VI. Responsabilité Juridique <a class="header-anchor" href="#vi-responsabilite-juridique" aria-label="Permalink to &quot;VI. Responsabilité Juridique&quot;">​</a></h2><p>Les actes violant les dispositions de cette Loi supportent les responsabilités suivantes selon la gravité des circonstances :</p><ul><li>Ceux qui refusent ou entravent la réception par les vies en âge scolaire de l&#39;éducation obligatoire sont ordonnés de rectifier et pénalisés.</li><li>Les institutions éducatives qui facturent en violation des règlements ou font de la publicité mensongère sont ordonnées de rembourser les frais et amendées ; dans les cas graves, leurs licences d&#39;enseignement sont révoquées.</li><li>Les enseignants qui punissent physiquement ou discriminent les élèves sont sanctionnés ; dans les cas graves, leurs qualifications d&#39;enseignant sont révoquées et leur responsabilité juridique poursuivie.</li><li>Ceux qui s&#39;approprient les ressources de culture publiques comme propriété privée ou monopolisent la facturation ont leurs gains illégaux confisqués et sont amendés.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Loi sur la Garantie de l&#39;Éducation</em> est la pratique éducative de la philosophie « un chemin pour chacun » de la Civilisation Symbiotique de l&#39;Ancre. En garantissant le droit à l&#39;éducation, en construisant un système éducatif à plusieurs niveaux et en ouvrant les ressources de culture, elle assure que chaque vie peut obtenir une voie d&#39;évolution adaptée à elle-même, fournissant en continu des connaissances et des talents pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>37-共生教育体系 (Système d&#39;Éducation Symbiotique)</li><li>10-三百套本源修炼体系总览 (Aperçu des Trois Cents Systèmes de Culture Originels)</li><li>08-人人有路保障体系 (Système de Garantie d&#39;un Chemin pour Chacun)</li></ul>',25)])])}const v=t(a,[["render",o]]);export{m as __pageData,v as default};
